  "test": "import pytest
import logging
from langfuse.api.llm_connections.raw_client import RawLlmConnectionsClient
from langfuse.api.core.api_error import ApiError


class FakeResponse:
    def __init__(self, status_code, json_data, text):
        self.status_code = status_code
        self._json = json_data
        self.text = text
        self.headers = {}

    def json(self):
        return self._json


class FakeHttpxClient:
    def request(self, *args, **kwargs):
        # Simulate an unexpected 500 error response
        return FakeResponse(
            status_code=500,
            json_data={"error": "internal"},
            text="internal error",
        )


class FakeClientWrapper:
    def __init__(self):
        self.httpx_client = FakeHttpxClient()


def test_list_unexpected_status_logs_warning(caplog):
    client = RawLlmConnectionsClient(client_wrapper=FakeClientWrapper())
    caplog.set_level(logging.WARNING)
    with pytest.raises(ApiError) as excinfo:
        client.list()
    # Verify that a warning was logged with the expected message
    warnings = [r for r in caplog.records if r.levelno == logging.WARNING]
    assert any(
        "Unexpected response status 500" in w.getMessage() for w in warnings
    ), "Expected warning about unexpected status code was not logged"
    # Ensure the ApiError contains the correct status code
    assert excinfo.value.status_code == 500"
}
